                break;
            case &quot;update&quot;:
                System.out.println(&quot;update&quot;); // FIXME
                break;
            case &quot;delete&quot;:
                System.out.println(&quot;delete&quot;); // FIXME
                break;
            case &quot;mark-in-progress&quot;:
                System.out.println(&quot;mark-in-progress&quot;); // FIXME
                break;
            case &quot;mark-done&quot;:
                System.out.println(&quot;mark-done&quot;); // FIXME
                break;
            case &quot;list&quot;:
                if (args.length &gt; 1) {
                    String subCommand = args[1].toLowerCase();
                    switch (subCommand) {
                        case &quot;done&quot;:
                            System.out.println(&quot;list done - Listing all completed tasks...&quot;);
                            break;
                        case &quot;todo&quot;:
                            System.out.println(&quot;list todo - Listing all tasks to do...&quot;);
                            break;
                        case &quot;in-progress&quot;:
                            System.out.println(&quot;list in-progress - Listing all in-progress tasks...&quot;);
                            break;
                        default:
                            System.out.println(&quot;Unknown filter: &quot; + subCommand);
                    }
                } else {
                    System.out.println(&quot;Listing all tasks...&quot;);
                }
                break;

            default:
                System.out.println(&quot;Please enter a valid command: &lt;command&gt; &lt;id&gt; &lt;description&gt; &lt;status&gt;&quot;);


        }


    }
}

